package com.transithub.shared.storage;

/**
 * Stores uploaded files (evidence, signatures) outside the database (R-17).
 *
 * <p>Implementations must encrypt at rest and keep data in Zambia
 * (ADR-0017). Keys are generated by the storage, never taken from user
 * input, so a file name can never point outside the store.
 */
public interface FileStorage {

    /** Stores the content and returns the key to read it back. */
    String store(byte[] content);

    /** @throws StoredFileNotFoundException if no file has this key */
    byte[] read(String key);

    class StoredFileNotFoundException extends RuntimeException {
        public StoredFileNotFoundException(String key) {
            super("No stored file with key " + key);
        }
    }
}
